import{_ as t,o as a,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"ADR 0002: Harden computation boundaries selectively; do not reactivate EngineCore","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0002-computation-layer-organization.md","filePath":"decisions/0002-computation-layer-organization.md","lastUpdated":1788546361000}'),n={name:"decisions/0002-computation-layer-organization.md"};function s(o,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="adr-0002-harden-computation-boundaries-selectively-do-not-reactivate-enginecore" tabindex="-1">ADR 0002: Harden computation boundaries selectively; do not reactivate EngineCore <a class="header-anchor" href="#adr-0002-harden-computation-boundaries-selectively-do-not-reactivate-enginecore" aria-label="Permalink to &quot;ADR 0002: Harden computation boundaries selectively; do not reactivate EngineCore&quot;">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-08-27</li><li><strong>Audience:</strong> maintainers and reviewers of computation, MCP and browser work</li><li><strong>Scope:</strong> repository state at <code>c46e9f0850aa07d1db7b6d65f6ab50b2cb2f9972</code></li><li><strong>Owns:</strong> computation-layer organization, duplication and refactor triggers</li><li><strong>Review when:</strong> a new engine variant is requested; a correctness defect is traced to engine inheritance; or a new scoring/MCP feature crosses the boundaries named below</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Keep the current frozen engines and additive module layout. Do <strong>not</strong> reactivate the parked <code>EngineCore</code> design from size or symmetry arguments alone. Improve the architecture through small contract-focused changes:</p><ol><li>correct the browser computations that already violate their selected-system or canonical-vocabulary contracts;</li><li>generate stable shared vocabularies where Python and TypeScript have the same semantics;</li><li>keep the generated activity-profile contract as the preferred ownership pattern;</li><li>document the actual bidirectional engine/derived assembly boundary;</li><li>defer broad MCP, Muhurta and engine restructuring until a named trigger is met; and</li><li>keep every correction or extraction in its own issue, branch and PR.</li></ol><p>This is a targeted correctness and change-efficiency decision, not a claim that the present file layout is ideal forever.</p><h2 id="reproducible-evidence" tabindex="-1">Reproducible evidence <a class="header-anchor" href="#reproducible-evidence" aria-label="Permalink to &quot;Reproducible evidence&quot;">​</a></h2><p>The static report reads the exact Git tree and the last 200 non-merge commits at the selected ref. It maps imports, computation owners/mirrors/consumers, cross-layer edges, direct test blast radius, private API use, engine method asymmetry, duplicate contract groups and file change concentration.</p><p>The JSON report retains schema version 1. Its source-count fields have these stable meanings:</p><table tabindex="0"><thead><tr><th><code>scope</code> field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>source_files</code></td><td>Total production Python and TypeScript modules. This is the original schema-v1 contract.</td></tr><tr><td><code>established_source_files</code></td><td>Modules in the established computation layer, excluding allowlisted additive feature modules.</td></tr><tr><td><code>additive_feature_source_files</code></td><td>Allowlisted feature modules layered around the established computation layer.</td></tr><tr><td><code>total_source_files</code></td><td>Explicit total, equal to <code>source_files</code> and to the sum of the established and additive counts.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/analyze_computation_architecture.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> c46e9f0850aa07d1db7b6d65f6ab50b2cb2f9972</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --commits</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --summary</span></span></code></pre></div><p>At that ref the report contains 78 production Python/TypeScript modules, 116 test files and all 62 computation records. The history window is exactly 200 non-merge commits, from <code>48d134dccebccc77e6251881280cd7a68c106ffc</code> through <code>81f292553a2ba22188fb6d6928630c8be9736cc0</code> among the measured source paths. The numbers below are evidence inputs, not architecture scores.</p><table tabindex="0"><thead><tr><th>File</th><th style="text-align:right;">Nonblank lines</th><th style="text-align:right;">Changed commits</th><th style="text-align:right;">Added + deleted lines</th><th style="text-align:right;">Direct linked tests</th><th style="text-align:right;">Computation IDs</th><th>Interpretation</th></tr></thead><tbody><tr><td><code>src/panels/tarabalam.ts</code></td><td style="text-align:right;">1,392</td><td style="text-align:right;">33</td><td style="text-align:right;">1,988</td><td style="text-align:right;">11</td><td style="text-align:right;">7</td><td>UI, browser astronomy and manual scorer mirrors share one boundary; correctness risk is higher than size alone suggests</td></tr><tr><td><code>telugu_panchangam/mcp/tools.py</code></td><td style="text-align:right;">1,239</td><td style="text-align:right;">62</td><td style="text-align:right;">1,466</td><td style="text-align:right;">59</td><td style="text-align:right;">0 owner IDs</td><td>High-change adapter/orchestration surface; heavily tested, but no computation should originate here</td></tr><tr><td><code>telugu_panchangam/personal/activity_rules.py</code></td><td style="text-align:right;">1,087</td><td style="text-align:right;">53</td><td style="text-align:right;">1,985</td><td style="text-align:right;">43</td><td style="text-align:right;">1</td><td>Mostly declarative, one Python owner, generated browser contract and per-profile provenance; size does not justify splitting it now</td></tr><tr><td><code>telugu_panchangam/personal/muhurta.py</code></td><td style="text-align:right;">895</td><td style="text-align:right;">52</td><td style="text-align:right;">4,061</td><td style="text-align:right;">38</td><td style="text-align:right;">1</td><td>Highest measured churn and a 283-line definition; rules and atomic scorers are already extracted, but orchestration remains a future split candidate</td></tr><tr><td><code>telugu_panchangam/engines/base.py</code></td><td style="text-align:right;">508</td><td style="text-align:right;">16</td><td style="text-align:right;">785</td><td style="text-align:right;">13</td><td style="text-align:right;">16</td><td>Large correctness blast radius but relatively low recent change; frozen-core posture is working as intended</td></tr></tbody></table><h3 id="import-and-output-consumer-map" tabindex="-1">Import and output-consumer map <a class="header-anchor" href="#import-and-output-consumer-map" aria-label="Permalink to &quot;Import and output-consumer map&quot;">​</a></h3><p>The complete module and 62-record output-consumer maps are emitted in JSON by the same command without <code>--summary</code>. Important current boundaries are:</p><ul><li><code>PanchangamDay</code> is the central public result, but engine finalization is not one-directional. <code>engines/base.py</code> imports ten additive derived modules to populate fields such as Ghati, Vishaghati, Bhadra, Panchaka, special Yogas, month flags and Sankramana avoidance.</li><li>Derived calendar modules import <code>engines/utils.py</code> for Julian-Day, sunrise and sidereal helpers. This creates an engine/derived utility seam, not a cycle through the engine classes.</li><li>MCP, build and Muhurta code import the three concrete engine modules because <code>engines/__init__.py</code> is empty. The root architecture&#39;s earlier example <code>from telugu_panchangam.engines import DrikGanitaEngine</code> is not a supported façade today.</li><li>MCP imports private <code>_validate_ayanamsa</code>, <code>_nak_index</code> and <code>_rasi_index</code>; <code>personal/homa.py</code> calls <code>engine._sun_longitude_func</code>. These are test-covered boundary leaks, not reasons to edit the frozen core in this assessment.</li><li>Every computation record lists its Python owner, TypeScript mirror where applicable, public surfaces and direct tests. MCP serialization is a consumer/adaptor even where its file has no owner ID.</li></ul><h3 id="duplicate-contract-map" tabindex="-1">Duplicate contract map <a class="header-anchor" href="#duplicate-contract-map" aria-label="Permalink to &quot;Duplicate contract map&quot;">​</a></h3><p>The analyzer records eight cross-surface contract groups. Activity profiles already use the selected pattern: Python owner → generated JSON → check-mode generator → browser consumer. Seven other groups remain manual mirrors:</p><ol><li>Rashi vocabulary (four locations);</li><li>Nakshatra vocabulary;</li><li>Nitya Yoga names and disposition;</li><li>special-Yoga tables;</li><li>Hora tables;</li><li>Homa election rules; and</li><li>named Shani conditions.</li></ol><p>Manual duplication is not automatically wrong. Homa and named-Shani mirrors, for example, have focused tests. It becomes a consolidation priority when the same semantics can be generated without moving executable judgment into data, or when a real mismatch appears.</p><p>Two real mismatches did appear:</p><ul><li>the browser slot evaluator always uses Meeus/Lahiri astronomy, even after a user selects Surya Siddhanta or Vakya (<a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/182" target="_blank" rel="noreferrer">#182</a>);</li><li>the browser emits <code>Priti</code>, <code>Shula</code>, <code>Variyana</code> while Python owns <code>Preeti</code>, <code>Shoola</code>, <code>Variyan</code>, bypassing some Nitya-Yoga lookups (<a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/183" target="_blank" rel="noreferrer">#183</a>).</li></ul><p>The shared-vocabulary prevention work is isolated in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/184" target="_blank" rel="noreferrer">#184</a>. Previously found output-contract defects remain separate in <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/179" target="_blank" rel="noreferrer">#179</a> and <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/180" target="_blank" rel="noreferrer">#180</a>.</p><h2 id="three-efficiency-questions" tabindex="-1">Three efficiency questions <a class="header-anchor" href="#three-efficiency-questions" aria-label="Permalink to &quot;Three efficiency questions&quot;">​</a></h2><h3 id="_1-runtime-efficiency" tabindex="-1">1. Runtime efficiency <a class="header-anchor" href="#_1-runtime-efficiency" aria-label="Permalink to &quot;1. Runtime efficiency&quot;">​</a></h3><p>The current Python paths do not provide a runtime driver for a core rewrite. The repeatable comparison command is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/benchmark_computation_paths.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2026-01-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --facts-per-day</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span></span></code></pre></div><p>On the recorded Apple-silicon/macOS/Python 3.11.15 run, warm 30-day Hyderabad calculation medians with eclipse search disabled were 0.169 seconds (Drik), 0.065 seconds (Surya Siddhanta) and 0.067 seconds (Vakya). Evaluating 120 slot facts took 0.0020, 0.0004 and 0.0004 seconds respectively. These figures are hardware-dependent and not CI thresholds; they show only that no measured Python bottleneck currently pays for an <code>EngineCore</code> migration.</p><p>The browser&#39;s local approximation is fast and static-host friendly, but its selected-system mismatch is a correctness problem. #182 must compare compact generated transition data against keeping client-side calculations before any runtime/data-size decision.</p><h3 id="_2-developer-change-efficiency" tabindex="-1">2. Developer change efficiency <a class="header-anchor" href="#_2-developer-change-efficiency" aria-label="Permalink to &quot;2. Developer change efficiency&quot;">​</a></h3><p>Change concentration is highest in MCP tools, activity profiles, Muhurta orchestration and the Tarabalam panel. Their treatments differ:</p><ul><li>keep declarative activity profiles together while their generator, provenance audit and profile tests isolate changes;</li><li>generate identical vocabularies rather than retyping them;</li><li>make MCP remain an adapter and split it by domain only when the next tool or shared validation change would otherwise enlarge <code>mcp/tools.py</code> again;</li><li>use #182 as the trigger to establish a pure browser slot-fact boundary, but do not hide its correction inside an unrelated panel rewrite; and</li><li>split Muhurta day admission, candidate construction and ranking only when a new scoring signal needs to cross more than one of those phases.</li></ul><h3 id="_3-correctness-and-verification-risk" tabindex="-1">3. Correctness and verification risk <a class="header-anchor" href="#_3-correctness-and-verification-risk" aria-label="Permalink to &quot;3. Correctness and verification risk&quot;">​</a></h3><p>Engine and scorer files have large direct test blast radii. That makes a broad rewrite more expensive, not more urgent. The safe verification unit is the stable computation ID and its existing public outputs:</p><ul><li>frozen-engine work requires explicit owner approval and multi-city, multi-date external comparison plus byte/field parity where relevant;</li><li>a browser mirror needs cross-language boundary fixtures, not merely separate Python and TypeScript unit tests that encode the same mistake;</li><li>generated data needs a check-mode command and stale-artifact test;</li><li>MCP extraction must retain all 17 tool signatures and serialized responses; and</li><li>an internal split must prove unchanged public output before claiming lower correctness risk.</li></ul><h2 id="recommendation-record" tabindex="-1">Recommendation record <a class="header-anchor" href="#recommendation-record" aria-label="Permalink to &quot;Recommendation record&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classification</th><th>Affected boundary</th><th>Expected benefit</th><th>Migration/correctness risk</th><th>Verification strategy</th><th>Owner approval?</th></tr></thead><tbody><tr><td><strong>Keep</strong></td><td><code>activity_rules.py</code> as one declarative owner</td><td>One auditable catalogue and stable generation order</td><td>Splitting now would add imports/order failure modes without reducing rule semantics</td><td>Existing provenance, export, selector and per-profile tests</td><td>No, while behavior is unchanged</td></tr><tr><td><strong>Clarify boundary</strong></td><td>engine finalization ↔ additive derived fields</td><td>Accurate mental model; contributors know that <code>PanchangamDay</code> assembly is an aggregator</td><td>Documentation-only</td><td>Analyzer edge map + computation inventory</td><td>No</td></tr><tr><td><strong>Correct, then split narrowly</strong></td><td>browser slot facts inside <code>tarabalam.ts</code></td><td>Selected-system correctness and an independently testable pure boundary</td><td>High: changes candidate admission/scoring near transitions</td><td>#182 differential fixtures for 3 systems, multiple dates/cities; screenshots for visible changes</td><td>UI sign-off; no frozen-core approval if engines remain untouched</td></tr><tr><td><strong>Consolidate/generate</strong></td><td>stable Python/TypeScript vocabulary arrays</td><td>Removes typo/order drift while keeping one owner</td><td>Medium: transliteration aliases and display spellings can be lost</td><td>#183 correction first; #184 generated artifact check + full browser parity</td><td>No frozen-core approval; UI sign-off for visible labels</td></tr><tr><td><strong>Clarify, then defer</strong></td><td>MCP private validators/index helpers and empty engine package façade</td><td>Makes supported API explicit without inventing a premature public library</td><td>Medium if engine imports change; current private calls are test-covered</td><td>Preserve 17 signatures/responses; add import-contract tests when a façade is proposed</td><td>Yes if any frozen engine/utility file changes</td></tr><tr><td><strong>Split on trigger</strong></td><td><code>mcp/tools.py</code> by tool domain</td><td>Smaller review surface and less merge contention</td><td>Medium: serialization/signature drift</td><td>Snapshot every tool schema/response and keep <code>mcp/server.py</code> thin</td><td>No unless computation behavior changes</td></tr><tr><td><strong>Split on trigger</strong></td><td><code>personal/muhurta.py</code> admission, candidates, ranking</td><td>Localized scoring changes and smaller function-level blast radius</td><td>High because ordering, reasons and tier caps are public behavior</td><td>Cross-surface golden candidates/reasons plus full current tests</td><td>No for byte/field-identical extraction; yes if frozen inputs change</td></tr><tr><td><strong>Defer</strong></td><td>parked <code>EngineCore</code> composition design</td><td>Would reduce method-name duplication and make variants pluggable</td><td>Very high: 3 systems, 16 base-owned computation IDs, many consumers and frozen tests</td><td>Dual-run byte/field parity, forward external fixtures, bulk benchmark</td><td><strong>Yes; explicit owner approval required</strong></td></tr></tbody></table><h2 id="why-enginecore-remains-parked" tabindex="-1">Why EngineCore remains parked <a class="header-anchor" href="#why-enginecore-remains-parked" aria-label="Permalink to &quot;Why EngineCore remains parked&quot;">​</a></h2><p>The analyzer confirms asymmetry: Drik and Surya Siddhanta directly subclass <code>PanchangamEngine</code>; Vakya subclasses Surya Siddhanta; ten method names are defined in all three concrete classes. It also confirms why this is not enough to reactivate the old plan:</p><ul><li>no new engine variant is requested;</li><li>recent engine change concentration is below the MCP/scoring/browser hotspots;</li><li>the local runtime comparison exposes no current performance problem;</li><li>#176 concerns the source and fidelity of the provisional Vakya lunar model, not a defect caused by inheritance duplication;</li><li>#177 concerns the shared rise/set convention, not divergent duplicated method bodies; and</li><li>the new concrete defects #179, #180, #182 and #183 all live outside the engine inheritance problem.</li></ul><p>Reactivation requires either a requested fourth engine/system variant or a verified bug whose cause is duplicated/inherited engine orchestration. At that point the old design is an option to reassess, not a pre-approved migration.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The repository gains repeatable architecture and runtime evidence tools, but no runtime module or frozen test assertion changes.</li><li>Large files are not split merely to improve a line-count statistic.</li><li>Browser calculation parity becomes the first correctness priority from this assessment.</li><li>Generated contracts are preferred for stable shared data; executable rules remain code with differential tests unless safe generation is demonstrated.</li><li>Deferred refactors retain explicit triggers, risks and approval gates instead of returning as unbounded cleanup work.</li></ul>`,43)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
